   109→        if let Some(blob_params) = &blob_params {
   110→            cfg_env.set_max_blobs_per_tx(blob_params.max_blobs_per_tx);
   111→        }
   112→
   113→        if chain_spec.is_osaka_active_at_timestamp(input.timestamp) {
   114→            cfg_env.tx_gas_limit_cap = Some(MAX_TX_GAS_LIMIT_OSAKA);
   115→        }
   116→
   117→        // if the parent block did not have excess blob gas (i.e. it was pre-cancun), but it is
   118→        // cancun now, we need to set the excess blob gas to the default value(0)
   119→        let blob_excess_gas_and_price = blob_params
   120→            .and_then(|blob_params| {
   121→                Some(blob_params.next_block_excess_blob_gas_osaka(
   122→                    input.excess_blob_gas?,
