use crate::EvmEnv;
use alloy_consensus::BlockHeader;
use alloy_eips::{eip7825::MAX_TX_GAS_LIMIT_OSAKA, eip7840::BlobParams};
use alloy_hardforks::EthereumHardforks;
use alloy_primitives::{Address, BlockNumber, BlockTimestamp, ChainId, B256, U256};
use revm::{
    context::{BlockEnv, CfgEnv},
    context_interface::block::BlobExcessGasAndPrice,
    primitives::hardfork::SpecId,
};

impl EvmEnv<SpecId> {
    /// Create a new `EvmEnv` with [`SpecId`] from a block `header`, `chain_id`, `chain_spec` and
    /// optional `blob_params`.
    ///
    /// # Arguments
    ///
    /// * `header` - The block to make the env out of.
    /// * `chain_spec` - The chain hardfork description, must implement [`EthereumHardforks`].
    /// * `chain_id` - The chain identifier.
    /// * `blob_params` - Optional parameters that sets limits on gas and count for blobs.
    pub fn for_eth_block(
        header: impl BlockHeader,
        chain_spec: impl EthereumHardforks,
        chain_id: ChainId,
        blob_params: Option<BlobParams>,
    ) -> Self {
        Self::for_eth(EvmEnvInput::from_block_header(header), chain_spec, chain_id, blob_params)
    }

    /// Create a new `EvmEnv` with [`SpecId`] from a parent block `header`, `chain_id`, `chain_spec`
    /// and optional `blob_params`.
    ///
    /// # Arguments
    ///
    /// * `header` - The parent block to make the env out of.
    /// * `base_fee_per_gas` - Base fee per gas for the next block.
    /// * `chain_spec` - The chain hardfork description, must implement [`EthereumHardforks`].
    /// * `chain_id` - The chain identifier.
    /// * `blob_params` - Optional parameters that sets limits on gas and count for blobs.
    pub fn for_eth_next_block(
        header: impl BlockHeader,
        attributes: NextEvmEnvAttributes,
        base_fee_per_gas: u64,
        chain_spec: impl EthereumHardforks,
        chain_id: ChainId,
        blob_params: Option<BlobParams>,
    ) -> Self {
        Self::for_eth_next(
            EvmEnvInput::from_parent_header(header, attributes, base_fee_per_gas),
            chain_spec,
            chain_id,
            blob_params,
        )
    }

    fn for_eth(
        input: EvmEnvInput,
        chain_spec: impl EthereumHardforks,
        chain_id: ChainId,
        blob_params: Option<BlobParams>,
    ) -> Self {
        let spec =
            crate::spec_by_timestamp_and_block_number(&chain_spec, input.timestamp, input.height);
        let mut cfg_env = CfgEnv::new_with_spec(spec).with_chain_id(chain_id);

        if let Some(blob_params) = &blob_params {
            cfg_env.set_max_blobs_per_tx(blob_params.max_blobs_per_tx);
        }

        if chain_spec.is_osaka_active_at_timestamp(input.timestamp) {
            cfg_env.tx_gas_limit_cap = Some(MAX_TX_GAS_LIMIT_OSAKA);
        }

        // derive the EIP-4844 blob fees from the header's `excess_blob_gas` and the current
        // blob-params
        let blob_excess_gas_and_price =
            input.excess_blob_gas.zip(blob_params).map(|(excess_blob_gas, params)| {
                let blob_gasprice = params.calc_blob_fee(excess_blob_gas);
                BlobExcessGasAndPrice { excess_blob_gas, blob_gasprice }
            });

        let is_merge_active = chain_spec.is_paris_active_at_block(input.height);

        let block_env = BlockEnv {
            number: U256::from(input.height),
            beneficiary: input.beneficiary,
            timestamp: U256::from(input.timestamp),
            difficulty: if is_merge_active { U256::ZERO } else { input.difficulty },
            prevrandao: if is_merge_active { input.mix_hash } else { None },
            gas_limit: input.gas_limit,
            basefee: input.base_fee_per_gas,
            blob_excess_gas_and_price,
        };

        Self::new(cfg_env, block_env)
    }

    fn for_eth_next(
        input: EvmEnvInput,
        chain_spec: impl EthereumHardforks,
        chain_id: ChainId,
        blob_params: Option<BlobParams>,
    ) -> Self {
        let spec =
            crate::spec_by_timestamp_and_block_number(&chain_spec, input.timestamp, input.height);
        let mut cfg_env = CfgEnv::new_with_spec(spec).with_chain_id(chain_id);

        if let Some(blob_params) = &blob_params {
            cfg_env.set_max_blobs_per_tx(blob_params.max_blobs_per_tx);
        }

        if chain_spec.is_osaka_active_at_timestamp(input.timestamp) {
            cfg_env.tx_gas_limit_cap = Some(MAX_TX_GAS_LIMIT_OSAKA);
        }

        // if the parent block did not have excess blob gas (i.e. it was pre-cancun), but it is
        // cancun now, we need to set the excess blob gas to the default value(0)
        let blob_excess_gas_and_price = blob_params
            .and_then(|blob_params| {
                Some(blob_params.next_block_excess_blob_gas_osaka(
                    input.excess_blob_gas?,
                    input.blob_gas_used?,
                    input.base_fee_per_gas,
                ))
            })
            .or_else(|| (spec == SpecId::CANCUN).then_some(0))
            .map(|excess_blob_gas| {
                let blob_gasprice =
                    blob_params.unwrap_or_else(BlobParams::cancun).calc_blob_fee(excess_blob_gas);
                BlobExcessGasAndPrice { excess_blob_gas, blob_gasprice }
            });

        let block_env = BlockEnv {
            number: U256::from(input.height),
            beneficiary: input.beneficiary,
            timestamp: U256::from(input.timestamp),
            difficulty: U256::ZERO,
            prevrandao: input.mix_hash,
            gas_limit: input.gas_limit,
            basefee: input.base_fee_per_gas,
            blob_excess_gas_and_price,
        };

        Self::new(cfg_env, block_env)
    }
}

pub(crate) struct EvmEnvInput {
    pub(crate) timestamp: BlockTimestamp,
    pub(crate) height: BlockNumber,
    pub(crate) beneficiary: Address,
    pub(crate) mix_hash: Option<B256>,
    pub(crate) difficulty: U256,
    pub(crate) gas_limit: u64,
    pub(crate) excess_blob_gas: Option<u64>,
    pub(crate) base_fee_per_gas: u64,
    pub(crate) blob_gas_used: Option<u64>,
}

impl EvmEnvInput {
    pub(crate) fn from_block_header(header: impl BlockHeader) -> Self {
        Self {
            timestamp: header.timestamp(),
            height: header.number(),
            beneficiary: header.beneficiary(),
            mix_hash: header.mix_hash(),
            difficulty: header.difficulty(),
            gas_limit: header.gas_limit(),
            excess_blob_gas: header.excess_blob_gas(),
            base_fee_per_gas: header.base_fee_per_gas().unwrap_or_default(),
            blob_gas_used: None,
        }
    }

    pub(crate) fn from_parent_header(
        header: impl BlockHeader,
        attributes: NextEvmEnvAttributes,
        base_fee_per_gas: u64,
    ) -> Self {
        Self {
            timestamp: attributes.timestamp,
            height: header.number() + 1,
            beneficiary: attributes.suggested_fee_recipient,
            mix_hash: Some(attributes.prev_randao),
            difficulty: header.difficulty(),
            gas_limit: attributes.gas_limit,
            excess_blob_gas: header.excess_blob_gas(),
            base_fee_per_gas,
            blob_gas_used: header.blob_gas_used(),
        }
    }
}

/// Represents additional attributes required to configure the next block.
///
/// This struct contains all the information needed to build a new block that cannot be
/// derived from the parent block header alone. These attributes are typically provided
/// by the consensus layer (CL) through the Engine API during payload building.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NextEvmEnvAttributes {
    /// The timestamp of the next block.
    pub timestamp: u64,
    /// The suggested fee recipient for the next block.
    pub suggested_fee_recipient: Address,
    /// The randomness value for the next block.
    pub prev_randao: B256,
    /// Block gas limit.
    pub gas_limit: u64,
}

#[cfg(feature = "engine")]
mod payload {
    use super::*;
    use alloy_rpc_types_engine::ExecutionPayload;

    impl EvmEnv<SpecId> {
        /// Create a new `EvmEnv` with [`SpecId`] from a `payload`, `chain_id`, `chain_spec` and
        /// optional `blob_params`.
        ///
        /// # Arguments
        ///
        /// * `header` - The block to make the env out of.
        /// * `chain_spec` - The chain hardfork description, must implement [`EthereumHardforks`].
        /// * `chain_id` - The chain identifier.
        /// * `blob_params` - Optional parameters that sets limits on gas and count for blobs.
        pub fn for_eth_payload(
            payload: &ExecutionPayload,
            chain_spec: impl EthereumHardforks,
            chain_id: ChainId,
            blob_params: Option<BlobParams>,
        ) -> Self {
            Self::for_eth(EvmEnvInput::from_payload(payload), chain_spec, chain_id, blob_params)
        }
    }

    impl EvmEnvInput {
        pub(crate) fn from_payload(payload: &ExecutionPayload) -> Self {
            Self {
                timestamp: payload.timestamp(),
                height: payload.block_number(),
                beneficiary: payload.fee_recipient(),
                mix_hash: Some(payload.as_v1().prev_randao),
                difficulty: payload.as_v1().prev_randao.into(),
                gas_limit: payload.gas_limit(),
                excess_blob_gas: payload.excess_blob_gas(),
                base_fee_per_gas: payload.saturated_base_fee_per_gas(),
                blob_gas_used: None,
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::eth::spec::EthSpec;
    use alloy_consensus::Header;
    use alloy_hardforks::ethereum::MAINNET_PARIS_BLOCK;
    use alloy_primitives::B256;

    #[test_case::test_case(
        Header::default(),
        EvmEnv {
            cfg_env: CfgEnv::new_with_spec(SpecId::FRONTIER).with_chain_id(2),
            block_env: BlockEnv {
                timestamp: U256::ZERO,
                gas_limit: 0,
                prevrandao: None,
                blob_excess_gas_and_price: None,
                ..BlockEnv::default()
            },
        };
        "Frontier"
    )]
    #[test_case::test_case(
        Header {
            number: MAINNET_PARIS_BLOCK,
            mix_hash: B256::with_last_byte(2),
            ..Header::default()
        },
        EvmEnv {
            cfg_env: CfgEnv::new_with_spec(SpecId::MERGE).with_chain_id(2),
            block_env: BlockEnv {
                number: U256::from(MAINNET_PARIS_BLOCK),
                timestamp: U256::ZERO,
                gas_limit: 0,
                prevrandao: Some(B256::with_last_byte(2)),
                blob_excess_gas_and_price: None,
                ..BlockEnv::default()
            },
        };
        "Paris"
    )]
    fn test_evm_env_is_consistent_with_given_block(
        header: Header,
        expected_evm_env: EvmEnv<SpecId>,
    ) {
        let chain_id = 2;
        let spec = EthSpec::mainnet();
        let blob_params = None;
        let actual_evm_env = EvmEnv::for_eth_block(header, spec, chain_id, blob_params);

        assert_eq!(actual_evm_env, expected_evm_env);
    }
}

//! Helpers to perform common calculations.

use alloy_consensus::constants::ETH_TO_WEI;
use alloy_hardforks::EthereumHardforks;
use alloy_primitives::BlockNumber;

/// Calculates the base block reward.
///
/// The base block reward is defined as:
///
/// - For Paris and later: `None`
/// - For Petersburg and later: `Some(2 ETH)`
/// - For Byzantium and later: `Some(3 ETH)`
/// - Otherwise: `Some(5 ETH)`
///
/// # Note
///
/// This does not include the reward for including ommers. To calculate the full block reward, see
/// [`block_reward`].
///
/// # References
///
/// - Definition: [Yellow Paper][yp] (page 15, 11.3)
///
/// [yp]: https://ethereum.github.io/yellowpaper/paper.pdf
pub fn base_block_reward(spec: impl EthereumHardforks, block_number: BlockNumber) -> Option<u128> {
    if spec.is_paris_active_at_block(block_number) {
        None
    } else {
        Some(base_block_reward_pre_merge(spec, block_number))
    }
}

/// Calculates the base block reward __before__ the merge (Paris hardfork).
///
/// Caution: The caller must ensure that the block number is before the merge.
pub fn base_block_reward_pre_merge(
    spec: impl EthereumHardforks,
    block_number: BlockNumber,
) -> u128 {
    if spec.is_constantinople_active_at_block(block_number) {
        ETH_TO_WEI * 2
    } else if spec.is_byzantium_active_at_block(block_number) {
        ETH_TO_WEI * 3
    } else {
        ETH_TO_WEI * 5
    }
}

/// Calculates the reward for a block, including the reward for ommer inclusion.
///
/// The base reward should be calculated using [`base_block_reward`]. `ommers` represents the number
/// of ommers included in the block.
///
/// # Examples
///
/// ```
/// # use alloy_hardforks::EthereumChainHardforks;
/// # use alloy_evm::block::calc::{base_block_reward, block_reward};
/// # use alloy_consensus::constants::ETH_TO_WEI;
/// # use alloy_primitives::U256;
/// #
/// // This is block 126 on mainnet.
/// let block_number = 126;
/// let number_of_ommers = 1;
///
/// let reward = base_block_reward(EthereumChainHardforks::mainnet(), block_number)
///     .map(|reward| block_reward(reward, 1));
///
/// // The base block reward is 5 ETH, and the ommer inclusion reward is 1/32th of 5 ETH.
/// assert_eq!(reward.unwrap(), ETH_TO_WEI * 5 + ((ETH_TO_WEI * 5) >> 5));
/// ```
///
/// # References
///
/// - Definition: [Yellow Paper][yp] (page 15, 11.3)
///
/// [yp]: https://ethereum.github.io/yellowpaper/paper.pdf
pub const fn block_reward(base_block_reward: u128, ommers: usize) -> u128 {
    base_block_reward + (base_block_reward >> 5) * ommers as u128
}

/// Calculate the reward for an ommer.
///
/// # Application
///
/// Rewards are accumulative, so they should be added to the beneficiary addresses in addition to
/// any other rewards from the same block.
///
/// From the yellow paper (page 15):
///
/// > If there are collisions of the beneficiary addresses between ommers and the block (i.e. two
/// > ommers with the same beneficiary address or an ommer with the same beneficiary address as the
/// > present block), additions are applied cumulatively.
///
/// # References
///
/// - Implementation: [OpenEthereum][oe]
/// - Definition: [Yellow Paper][yp] (page 15, 11.3)
///
/// [oe]: https://github.com/openethereum/openethereum/blob/6c2d392d867b058ff867c4373e40850ca3f96969/crates/ethcore/src/ethereum/ethash.rs#L319-L333
/// [yp]: https://ethereum.github.io/yellowpaper/paper.pdf
pub const fn ommer_reward(
    base_block_reward: u128,
    block_number: BlockNumber,
    ommer_block_number: BlockNumber,
) -> u128 {
    ((8 + ommer_block_number - block_number) as u128 * base_block_reward) >> 3
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloy_hardforks::EthereumChainHardforks;
    use alloy_primitives::U256;

    #[test]
    fn calc_base_block_reward() {
        // ((block number, td), reward)
        let cases = [
            // Pre-byzantium
            ((0, U256::ZERO), Some(ETH_TO_WEI * 5)),
            // Byzantium
            ((4370000, U256::ZERO), Some(ETH_TO_WEI * 3)),
            // Petersburg
            ((7280000, U256::ZERO), Some(ETH_TO_WEI * 2)),
            // Merge
            ((15537394, U256::from(58_750_000_000_000_000_000_000_u128)), None),
        ];

        for ((block_number, _td), expected_reward) in cases {
            assert_eq!(
                base_block_reward(EthereumChainHardforks::mainnet(), block_number),
                expected_reward
            );
        }
    }

    #[test]
    fn calc_full_block_reward() {
        let base_reward = ETH_TO_WEI;
        let one_thirty_twoth_reward = base_reward >> 5;

        // (num_ommers, reward)
        let cases = [
            (0, base_reward),
            (1, base_reward + one_thirty_twoth_reward),
            (2, base_reward + one_thirty_twoth_reward * 2),
        ];

        for (num_ommers, expected_reward) in cases {
            assert_eq!(block_reward(base_reward, num_ommers), expected_reward);
        }
    }
}

